package com.utec.tropelcare.controller; import com.utec.tropelcare.dto.*; import com.utec.tropelcare.service.SectorService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/sectors") public class SectorController{private final SectorService s;public SectorController(SectorService s){this.s=s;}@PostMapping public ResponseEntity<SectorDto> create(@Valid @RequestBody SectorRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));}@GetMapping public List<SectorDto> all(){return s.all();}@GetMapping("/{id}") public SectorDto get(@PathVariable Long id){return s.get(id);}}
